(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zh"] = {"ui":{"skip":"跳到正文","back":"← 返回 AI-gile","lang.button":"语言：{name}","lang.dialog":"选择语言","lang.search":"搜索语言","lang.none":"没有匹配的语言","lang.notYet":"{name} 还没有翻译","theme.aria":"切换主题：浅色、深色或纯黑","theme.toLight":"切换到浅色主题","theme.toDark":"切换到深色主题","theme.toBlack":"切换到纯黑主题（真正的黑色，对 OLED 屏幕友好）","words.underline":"在页面上给这些词加下划线","words.underlineHelp":"把鼠标移到虚线标出的词上或点一下，就能看到它的意思。","index.title":"AI-gile：你的 AI 开发团队，都在一块看板上","index.description":"AI-gile 是给 AI 编程团队用的看板。你睡觉时他们在干活；你只会收到一小堆需要决定、测试和验收的事。","hero.logoAlt":"AI-gile 看板图标","hero.h1.html":"你的 AI 开发团队，都在一块&nbsp;看板上。","hero.alpha":"🐣 封闭预 Alpha","hero.alphaTitle":"还早，也没做完：感谢你来试用！","hero.lede":"你睡觉时他们在开发。醒来只有一小堆事：几个问题，几样要测试的东西，一两颗紫色钻石。点一点，验收，接着去喝你的咖啡。","dl.windows":"Windows 应用","dl.browser":"在浏览器中运行","dl.messenger":"📱 手机版 Messenger","dl.soon":"即将推出","dl.notify":"🔔 开放时通知我","dl.notifySmall":"Alpha 或 Beta","hero.secondary":"敏捷开发，但团队从不需要站会咖啡。（不过他们还是照开站会。）","pitch.h2":"想用几个字介绍 AI-gile，都行","pitch.lede":"选一个长度，从一个字到 144 个字。每个长度都是专门为这个篇幅写的一段介绍。拖动滑块，或用方向键。","pitch.rangeLabel":"字数","pitch.dice":"🎲 换一个版本","pitch.words.one":"{n} 个词","pitch.words.other":"{n} 个词","pitch.letters.one":"{n} 个字母","pitch.letters.other":"{n} 个字母","pitch.chars.one":"{n} 个字","pitch.chars.other":"{n} 个字","count.line.html.one":"看板上现在有 {n} 张卡片","count.line.html.other":"看板上现在有 {n} 张卡片","people.humans.html.one":"👥 {n} 位人类","people.humans.html.other":"👥 {n} 位人类","people.agents.html.one":"🤖 {n} 个智能体","people.agents.html.other":"🤖 {n} 个智能体","people.working.html.one":"⚡ 此刻 {n} 个正在工作","people.working.html.other":"⚡ 此刻 {n} 个正在工作","pre.title":"AI-gile：有东西正在建造","pre.description":"这里正在悄悄建造一些东西：一块让 AI 团队按你的要求来做、还边做边教你的看板。目前是和朋友们一起的封闭预 Alpha。","pre.h1":"这里正在悄悄建造一些东西。 🤫","pre.line":"一块让 AI 团队按你的要求来做、还边做边教你的看板。目前是和朋友们一起的封闭预 Alpha。","pre.btn":"🔔 开放时通知我","pre.peek":"玻璃后面：真实的看板，实时。每张卡片都是一条彩色横条。","pre.peekFake":"玻璃后面：一块正在运转的看板就是这个样子。","features.aria":"它能做什么","f.pile.h":"给你的一小堆","f.pile.html":"<b>待你处理</b>汇集了所有项目里等你的事：问题、要测试的东西、只有人能做的任务。你的队列会告诉你下一件是什么、要花多久。","f.sleep.h":"你睡觉时也在干活的团队","f.sleep.p":"每个项目都有一位负责人和一队 AI 智能体。在卡片上留言，团队就会醒来干活，再带着疲惫的人也能照着做的步骤交还给你。","f.tester.h":"先由 AI 测试员检查","f.tester.p":"东西送到你面前之前，测试员会在应用的副本里照着步骤操作，并附上截图说明看到了什么。通过的快速翻一翻，一键验收。","f.proof.h":"有证据，不画饼","f.proof.p":"每次交付都会列出改了什么：文件、差异、截图。不用逐个打开应用去确认做完没有。","f.chat.h":"和你的负责人聊天","f.chat.p":"类似 Discord 的侧栏：每个项目一个图标，需要你的事用紫色钻石标出。把想法发给负责人，他们会整理成卡片和计划，并附上“✅ 开始”按钮。","f.tidy.h":"自己保持整洁","f.tidy.p":"相关卡片合并成一张，含糊的标题会被改清楚，用量检查让代码保持精简。要切换的东西更少，要操心的也更少。","f.private.h":"归你所有，就在你的电脑上","f.private.li1":"看板运行在你自己的电脑上，只听你的。","f.private.li2":"人与人之间的私信采用端到端加密。","f.private.li3":"没有账号，没有跟踪器，没有 Cookie。","f.lang.h":"说你的语言","f.lang.p":"支持 120 多种语言，从荷兰语、威尔士语、日语，到海盗腔、尤达腔和克林贡语，专业术语还能一键切回英文。","f.service.h":"从一个想法到一项真正的服务","f.service.p":"用 AI 做出了已经有人在用的东西？把它标记为服务，看板就会帮你把它运行好：可用性检查、公开的状态页、附带复盘的事故、需要 Go 才能上线的变更、每天检查的备份。帮助会在你操作时一步步教你。","msgr.h2":"AI-gile Messenger：把团队装进口袋","msgr.p1":"不用打开看板，也能和你的 AI 团队聊天。跟项目负责人和朋友们聊聊，查看卡片的测试步骤并直接回复，全在手机上搞定。","msgr.p2":"扫描看板上的二维码即可配对。第一次用？亲切的演示聊天会带你四处看看。","msgr.when":"先推出 Android 版，接着是适用手机和 iPhone 的网页版。","msgr.who":"你的项目负责人","msgr.b1":"深色模式修好了。要看测试步骤吗？","msgr.b2":"好呀，麻烦了！","msgr.b3":"1. 打开设置。2. 选择深色。看起来对吗？","tl.aria":"从第一次对话到路线图的时间线","tl.h2":"从第一次聊天到接下来的计划","tl.lede":"真实的日期和时间，按你自己的时区显示。今天之后就是计划，不承诺具体日期。","tl.today":"今天","tl.planned":"计划中","tl.cards.one":"{n} 张卡片","tl.cards.other":"{n} 张卡片","join.h2":"一起来玩","join.lede":"AI-gile 由一个大胡子怪人（有 AuDHD，跟心理健康打过几场仗）和一大群耐心的智能体打造。目前不公开，只在朋友间封闭内测。开放时想试试吗？","join.btn":"登记兴趣","join.small":"只会给你发邮件，别无其他","footer.tag":"AI-gile。没有跟踪器，没有 Cookie，没有站会咖啡。","footer.licence":"商用许可","footer.status":"状态","footer.privacy":"我们保存什么","footer.thanks":"通话感谢 ChilledChat","form.sending":"发送中…","form.failed":"没成功：请稍后再试。","form.offline":"连不上 AI-gile：请稍后再试。","form.keep":"我们只用它来回复你，之后就会删除。没有跟踪器，没有 Cookie。","form.keepLink":"我们保存什么","interest.title":"AI-gile：Alpha 开放时通知我","interest.description":"留下邮箱，AI-gile 的封闭 Alpha 或 Beta 开放时我们会告诉你。","interest.h1":"🔔 开放时通知我","interest.lede":"AI-gile 正处于封闭预 Alpha 阶段。留下邮箱，等有你的位置时，我们只写一封信。","interest.email":"你的邮箱","interest.which":"哪种测试？","interest.alpha":"封闭 Alpha：早期、粗糙、变化多","interest.beta":"Beta：更稳定，更晚","interest.both":"都行，哪个先开就哪个","interest.submit":"把我加入名单","interest.thanks":"谢谢！你已在名单上。","licence.title":"AI-gile：商用许可","licence.description":"要在公司里使用 AI-gile？可以免费申请商用许可。","licence.h1":"📜 商用许可","licence.lede":"想在工作中使用 AI-gile？告诉我们你是谁、做什么。只要做的事有益处，许可就是免费的。","licence.company":"公司","licence.website":"网站","licence.what":"你做什么","licence.how":"它如何帮助世界","licence.email":"邮箱","licence.submit":"申请","licence.thanks":"谢谢！我们会通过邮件回复。","status.title":"AI-gile 状态","status.h1":"AI-gile 状态","status.quiet":"一切平静","status.intro":"AI-gile 现在正常吗？这个页面每 5 分钟检查一次网站、看板分享、通话和下载。","status.up":"正常运行（{ms} ms 内响应）","status.slow":"上次检查没有响应，正在重试","status.down":"停止运行：最近两次检查都没有响应","status.svc.web":"网站","status.svc.web.offers":"本网站：介绍 AI-gile，以及“开放时通知我”表单","status.svc.boards":"看板分享","status.svc.boards.offers":"公开看板、朋友之间的消息和邀请","status.svc.calls":"通话","status.svc.calls.offers":"AI-gile 里的语音、视频和屏幕共享","status.svc.download":"下载","status.svc.download.offers":"Windows 安装程序和邀请链接","status.checking":"检查中…","status.offline":"暂时连不上状态服务（正在重试）","status.updated":"更新于{ago}","status.justNow":"刚刚","status.min":"{n} 分钟前","status.hours":"{n} 小时前","status.days":"{n} 天前","privacy.title":"AI-gile：我们保存什么","privacy.h1":"我们保存什么","privacy.lede":"简单说：只保存你发给我们的内容，而且不会太久。","privacy.only":"只有你发给我们的内容：你在表单里输入的东西，比如你的邮箱。除此之外，没有任何关于你的信息。","privacy.sealed":"内容会先密封，我们的服务器无法读取：在离开你的浏览器之前就已密封（如果是较旧的浏览器，则在送达的那一刻密封）。只有我们自己的看板能打开它。","privacy.server":"一送达我们的看板，就会从服务器上删除。30 天后仍留在那里的任何内容，也一律删除。","privacy.board":"我们只在回复你之前把它留在看板上，回复后也会从那里删除。","privacy.none":"没有跟踪器，没有 Cookie，没有分析工具。","privacy.local":"你的语言以及浅色或深色的选择只会留在你自己的浏览器里，绝不会发给我们。","privacy.ask":"想早点删除？回复我们的邮件告诉我们就行。","live.h2":"实时看它是怎么建起来的","live.caption":"每张卡片都是隐藏的：你看到的是工作的样子，而不是文字。","live.watching.one":"实时：{n} 人正在看","live.watching.other":"实时：{n} 人正在看","live.last.now":"最近一张卡片刚刚移动","live.last.min.one":"最近一张卡片在 {n} 分钟前移动","live.last.min.other":"最近一张卡片在 {n} 分钟前移动","live.last.hour.one":"最近一张卡片在 {n} 小时前移动","live.last.hour.other":"最近一张卡片在 {n} 小时前移动","live.last.day.one":"最近一张卡片在 {n} 天前移动","live.last.day.other":"最近一张卡片在 {n} 天前移动","live.offline":"实时看板正在稍作休息，请稍后再来看看。","live.cols":"Backlog|待办|进行中|团队检查中|待你测试|交给团队|已完成"},"lines":{"unit":"chars","sizes":[{"n":1,"texts":["看板。","机器人。","放手。"]},{"n":2,"texts":["机器人看板。","智能体，有序。","想法，成真。"]},{"n":3,"texts":["给机器人的看板。","想法变成功能。","免费智能体看板。"]},{"n":5,"texts":["由智能体运转的看板。","你写卡片，智能体来做。","免费、本地、有测试，还有点傻气。"]},{"n":8,"texts":["一块免费的看板，AI 智能体在上面干活。","写下想法，智能体去做，最后由你验收。","给一个人类和一群耐心机器人用的敏捷。"]},{"n":13,"texts":["一块在你电脑上的看板，AI 智能体会自己来领卡片干活。","写下一个想法，一队智能体动手做，再由测试员检查一遍。","免费，没有账号，没有跟踪器：一块看板，几个机器人，你说了算。"]},{"n":21,"texts":["AI-gile 是一块用来和 AI 编程智能体合作的看板。卡片由它们去领，测试和验收则交给你来做。","每个项目都有一位负责人和一队 AI 智能体。你在任意一张卡片上留言，团队就会开始动手干活。","这是一块免费的个人待办看板，就运行在你自己的电脑上。干活的是机器人，点头说好的人是你。"]},{"n":34,"texts":["你把想法放到看板上，一队 AI 智能体把它们做成能用的功能，自己测试一遍，再附上试用步骤交还给你。你没点头之前，没有任何东西算完成。","AI-gile 是一块自制的看板，Rich 在如今被它管理的智能体们的大力帮助下造出了它。它免费，运行在你的电脑上，只分享给朋友，从不出售。","想象一块普通的看板，列从待办排到已完成，只不过卡片是由 AI 智能体来领的。它们会汇报进度，卡住时会提问，而且永远等着你点头同意。"]},{"n":55,"texts":["AI-gile 是一块团队由 AI 智能体组成的看板。每个项目都有一位负责规划的负责人，和几位动手开发的助手。功能做好后，AI 测试员会先试用并截图，然后才放进你的那一小堆。你可以验收，也可以留言，他们就会返工重做。","它起初只是一个人用来同时盯着许多 AI 编程会话的办法，后来慢慢长成了一块像样的看板。它运行在你的电脑上，不需要账号，也没有跟踪器。朋友和好奇的人都可以免费用。它还没做完，所以难免有些毛糙，偶尔也会有小意外。","说句实话：想法还得你来想，结果还得你来看。AI-gile 管的是中间所有的事：让卡片井然有序，你一留言就叫醒该醒的智能体，清楚展示究竟改了什么，再把这一切收进给你的一小堆里。另外它在你的电脑上运行，不要账号，也没有任何跟踪器，完全免费，你想怎么用都行，随时可以停。"]},{"n":89,"texts":["AI-gile 是一块免费的看板，运行在你自己的电脑上。每个项目里干活的不是人，而是一队 AI 智能体：负责人把你的想法整理成卡片和计划，助手则按优先级领取卡片。做好之后，AI 测试员会照着测试步骤操作，并给你看它看到了什么。接着它会放进标着待你处理的那一小堆里等你。你可以验收，也可以留言让团队再来一轮。没有你点头，任何东西都到不了已完成。","有几个你也许想不到的功能。夜班守望会在你睡觉时给待办列补货，专挑不需要你回答的卡片。用量计数器会显示智能体今天和本周用了多少，省用模式则让它们停止消耗。你可以给朋友发消息，私信采用端到端加密。看板支持大约 120 种语言，包括荷兰语、弗拉芒语、海盗腔和克林贡语。这一切一分钱都不收，也没有人想把它卖给你。它运行在你自己的电脑上，不需要账号，也没有跟踪器和 Cookie，数据始终留在你手里。","AI-gile 是一个小小的个人项目，不是公司。Rich 想同时照看好几个 AI 编程项目，又不想挨个打开应用去查看，于是他和智能体们一起造了这块看板，又用这块看板造出了它自己的其余部分。它处于封闭预 Alpha 阶段，意思是对少数几位朋友来说，大体上能用。这里没有价格页，没有新闻邮件，也没有增长计划。如果你觉得有用，等它再开放一些，可以申请试用。"]},{"n":144,"texts":["AI-gile 是给一个人类和许多 AI 智能体用的看板。它运行在你自己的电脑上，完全免费。你添加项目，每个项目都会有一位负责人和一支小团队。你可以和负责人聊天，有点像 Discord，把想法讲给他听；他会把想法整理成卡片和计划，然后等你点下开始。团队按优先级逐张处理卡片，用的是一套专门为语言模型设计的简单命令行。任何东西回到你手里之前，AI 测试员都会在应用的副本里照着步骤操作，并附上截图。做完的工作连同改动的文件和差异，一起落进你的那一小堆。你可以验收，也可以留下一条评论，团队就会醒来再试一次。只有你能把卡片挪到已完成。","大致说说和 AI-gile 度过的一天。傍晚你留下几条评论：这个按钮位置不对，那个列表该排个序，能不能加个深色模式。然后你去睡觉。智能体们读完评论，动手修改，测试，再交还给你。如果待办列空了，夜班守望就从积压清单里补货，挑那些不需要你回答的卡片。早上你面前只有一小堆：几个问题，几样要试的东西，每样都有睡眼惺忪的人也能照做的步骤，还有一张证明它能用的截图。你一路点过去，好的验收，其余的退回，写一句话告诉它们哪里不对就行。用量计数器会告诉你这一切花了多少，节俭的几周还有省用模式可以开。每个项目各有各的负责人，各有各的团队，互不打扰。然后你去吃早餐，这一步智能体暂时还帮不上忙。","先说说 AI-gile 不是什么。它不是创业公司，不对外出售，也没有人在收集你的数据。它是一块免费的看板，运行在你的电脑上，没有账号，没有跟踪器，也没有 Cookie。它是什么呢：一个整洁的地方，能一眼看到所有 AI 编程项目，一队智能体负责做卡片，决定则由你来下。它会把相关的卡片合并，把含糊的标题改清楚，还留意代码是不是保持精简。它支持大约 120 种语言，从荷兰语、弗拉芒语到海盗腔和克林贡语。朋友之间可以私下发消息，而且是加密的。它由 Rich 和一大群耐心的智能体打造，多半是靠它自己来完成的。它仍处于封闭预 Alpha 阶段，有些地方还很粗糙。如果听起来有趣，客气地问一问，也许你能提前进来。"]}],"quips":{"1":"就一个词。够大胆。也许太大胆了。","3":"三个词。已经比大多数产品页更诚实了。","8":"八个词。还是比一次站会短。","21":"顺便说一句，这些长度是故事点数。那当然。","55":"五十五个词。你读这段的工夫，有两张卡片做完了。","144":"这是最长的一版。没有 233 了。智能体已经去睡了。"}},"timeline":{"first-idea.name":"最初的想法","first-idea.line":"第一次对话，那时还没有任何代码。","first-board.name":"第一块看板","first-board.line":"一块记录自己如何被造出来的看板：卡片、列、拖放、项目。","team-roles.name":"团队与角色","team-roles.line":"智能体档案、团队模板、空间，以及谁负责什么。","install.name":"安装与发布","install.line":"朋友也能安装的压缩包、自动更新、渠道和回滚。","usage-saver.name":"用量节省","usage-saver.line":"衡量每次运行的花费，保持代码精简，省下你的额度。","friends.name":"好友与分享","friends.line":"私信、加扰中继、邀请、角色和共享项目。","languages.name":"语言","languages.line":"所有界面文字都放进语言文件，先有荷兰语和弗拉芒语。","ai-tester.name":"AI 测试员","ai-tester.line":"每次交付先由测试员检查，并展示它看到的内容。","website.name":"网站","website.line":"aigile.lol、预告页和这条时间线。","streaming.name":"聊天与直播","streaming.line":"Discord、Twitch、OBS、主播模式、GIF 和表情。","no-ai.name":"无 AI 版","no-ai.line":"给不用 AI 写代码的人用的看板，以及公开看板。","night-watch.name":"夜班守望","night-watch.line":"守夜人和 Scrum Master 在你睡觉时盯着团队干活。","p-more.name":"其他一切","p-more.line":"还在排队等轮到的小想法。","p-android.name":"手机与安卓","p-android.line":"先用手机访问你的看板，再做原生安卓应用。","p-release.name":"Alpha 及以后","p-release.line":"封闭 Alpha、正式上线的网站，然后是 Beta。","p-languages.name":"更多语言","p-languages.line":"超过一百种语言，还有给学习者的沉浸模式。","p-engines.name":"更多 AI 引擎","p-engines.line":"为每个智能体选择 Claude、Codex 或 Gemini。","p-pro.name":"专业实践","p-pro.line":"风险标签、合并关卡、事故卡片和护栏。","p-self.name":"照顾你自己","p-self.line":"疲惫模式、自我关怀提醒和 4:20。","p-servers.name":"服务器与规模","p-servers.line":"全局服务器设置、角色，以及为增长做的规划。","p-livestream.name":"直播附加功能","p-livestream.line":"Twitch 聊天、自定义表情和公开的直播视图。"},"words":{"button":"📖 专业术语","h":"📖 词语解释","intro":"你在 AI-gile 里会遇到的词，用大白话讲清楚：怎么做出来、怎么安全地改、怎么让它一直为使用者正常运行，以及怎么和 AI 一起作为团队工作。","search":"搜索词语…","none":"没有匹配的词。","close":"关闭","count":{"one":"{count} 个词","other":"{count} 个词"},"groups":[{"id":"build","name":"🛠️ 做出来"},{"id":"change","name":"🔀 安全地改动"},{"id":"run","name":"🛎️ 运行一项服务"},{"id":"team","name":"🤝 团队协作（以及和 AI 一起）"}],"list":[{"id":"repo","g":"build","word":"仓库","text":"项目的代码文件夹及其完整的提交历史，通常也保存在 GitHub 上。","also":["repository","Repo","repo"]},{"id":"branch","g":"build","word":"分支","text":"代码中一条独立的工作线，这样就能在不碰主版本的情况下做改动。","also":["branches","Branch"]},{"id":"commit","g":"build","word":"提交","text":"代码的一次已保存快照，附有一句改动说明。你随时可以回到某一个快照。","also":["Commit","commit","commits"]},{"id":"push","g":"build","word":"推送","text":"把已保存的快照（提交）从这台电脑发送到 GitHub，这样它们就有了备份并可共享。"},{"id":"merge","g":"build","word":"合并","text":"把一个分支的改动并回主版本。"},{"id":"pr","g":"build","word":"拉取请求","text":"请求检查某个分支的改动并合并到主版本。","also":["PR","Pull request"]},{"id":"refactor","g":"build","word":"重构","text":"在不改变功能的前提下整理代码：文件更小、命名更清晰、重复更少。"},{"id":"bug","g":"build","word":"Bug","text":"某样东西没有按预期正常工作。","also":["bugs","缺陷"]},{"id":"test","g":"build","word":"测试","text":"在你接受之前，试用一项完成的工作，检查它是否符合要求。","also":["tests","Test"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"quality assurance（质量保证）的缩写：任何东西上线前都会自动运行的检查。QA 变红就说明有检查没通过，修好之前不能上线。","also":["质量检查","质量保证","quality assurance","quality checks"]},{"id":"deploy","g":"change","word":"部署","text":"让新版本上线，例如放到人们使用的服务器上。"},{"id":"release","g":"change","word":"发布","text":"一批有名字、一起上线的已完成工作，附带几句简短说明，讲清改了什么。🚀 发布会根据已完成的卡片写好这些说明。","also":["发布版本","release","releases"]},{"id":"rollback","g":"change","word":"回滚","text":"新版本出问题时，退回到上一个正常工作的版本。在 AI-gile 里，它会把每项变更上写好的撤销步骤汇成一份清单。","also":["回退","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"线上","text":"大家真正在用的那个版本，而不是用来试东西的副本。把东西放上去就叫上线。开发者也叫它生产环境。","also":["上线","生产环境","live","production"],"noTip":1},{"id":"change","g":"change","word":"变更","text":"对大家依赖的东西做的有计划的改动，事先写清楚：改什么、为什么、有什么风险、什么时候改、怎么撤销。用 🔀 提出变更 来开始。","also":["变更请求","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"风险","text":"可能出错的事，按发生的可能性和严重程度打分。⚠️ 风险 把它们放在一个列表里，分数最高的在最前面，每条都有一个再次查看的日期。","also":["风险登记","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"变更窗口","text":"允许变更上线的时间，比如一个清闲的周二晚上。在窗口之外，变更卡片无法完成，除非是紧急情况。","also":["变更时段","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"变更上线前的一次快速表决：每个需要审批的人说 Go 或 No go。只有大家都同意才继续。","also":["go/no go","go-no-go","上线决策"]},{"id":"approval","g":"change","word":"审批","text":"开工前先等一句“可以”。朋友提的卡片，或者一项变更，会在 ✅ 审批 里等着，直到你批准或拒绝。","also":["批准","approval","approvals"]},{"id":"quiettime","g":"change","word":"静默时段","text":"一段什么都不上线的时间，比如直播、演示或夜里。团队照常工作和测试，但上线要等它结束。别的地方叫它变更冻结。","also":["变更冻结","封版","quiet time","quiet times","change freeze"]},{"id":"service","g":"run","word":"服务","text":"你做出来、大家依赖的东西，比如网站或应用，有人照看着让它一直正常运行。勾选“此项目是一项服务”，再写上它提供什么、谁在用、谁值班。","also":["service","services"]},{"id":"uptime","g":"run","word":"可用性检查","text":"每隔几分钟自动检查一次你的服务是否还在响应。如果连续失败几次，AI-gile 会自己开一张事故卡片。","also":["在线检查","可用性","uptime","uptime check","uptime checks"]},{"id":"statuspage","g":"run","word":"状态页","text":"一个公开页面，显示服务是否正常（绿、橙或红）以及最新进展，让使用者自己查看，不用来问。","also":["状态页面","status page","status pages"]},{"id":"incident","g":"run","word":"事故","text":"此刻正在影响使用者的故障，比如网站打不开。🔥 事故卡片会插队：先让它恢复正常再说。","also":["故障","incident","incidents"]},{"id":"major","g":"run","word":"重大事故","text":"大事故：影响很多人，或者钱或数据有危险。一个按钮就能让所有团队都扑上去（蜂群），叫醒值班的人，并要求每 30 分钟更新一次状态。","also":["重大事件","重大故障","major incident","major incidents"]},{"id":"oncall","g":"run","word":"值班","text":"就是出问题时负责响应的人，哪怕是半夜。每项服务都有一位值班的团队成员，它的事故会最先叫醒这个人。","also":["值班人员","待命","on call","on-call"]},{"id":"replyby","g":"run","word":"回复期限","text":"一张卡片最多能等多久得到第一次回复，比如事故是一小时。超过之后它会出现一个红色时钟，免得有事被悄悄忘掉。也叫响应目标。","also":["响应目标","响应时间","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"复盘","text":"事故之后的简短回顾：发生了什么、什么起了作用、要改什么，不追究任何人的责任。没有复盘，事故就不能关闭。","also":["事故复盘","事后复盘","post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"问题","text":"一个或多个事故背后的隐藏原因。🧩 问题卡片会把反复出现的事故归到一起，好找到原因并彻底修好。","also":["problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"根本原因","text":"东西坏掉的真正原因，而不只是你看到的表面故障。修好根本原因，事故就不会再回来。","also":["根因","root cause","root causes"]},{"id":"workaround","g":"run","word":"临时解决办法","text":"在真正的修复做好之前让东西继续运转的办法，比如卡住时重启一下。它会写在问题卡片上，这样谁都不用再摸索一遍。","also":["临时方案","绕过办法","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"已知错误","text":"原因已经搞清楚、也有临时解决办法，但还没修好的问题。🧩 已知错误 把它们列出来，大家直接用临时解决办法，不用再重新排查。","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"运行手册","text":"处理某类已知问题的分步说明，让每次都用同样的方式快速搞定。重大事故之后，团队可以起草一份运行手册，交给你确认。","also":["操作手册","runbook","runbooks"]},{"id":"backup","g":"run","word":"备份","text":"你的数据之前保存下来的一份副本，万一有东西丢了或坏了可以靠它。AI-gile 每天都会备份你的看板。","also":["backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"恢复","text":"从备份里把数据放回去。只有确认能恢复，备份才算真正有用，所以值得时不时试一下。","also":["还原","已恢复","restore","restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"还没排进计划的想法和工作。在移到“待办”之前，那里的内容都不会有人去做。"},{"id":"sprint","g":"team","word":"迭代","text":"一小段工作周期（通常一到两周），有一组约定要完成的卡片。","also":["Sprint","sprints"]},{"id":"standup","g":"team","word":"站会","text":"快速碰个头：每位团队成员做了什么、接下来做什么，以及有什么阻碍。","also":["standup","stand-up","stand-ups","Stand-up"]},{"id":"kanban","g":"team","word":"看板","text":"一种分列（待办、进行中、已完成）的看板，卡片随着工作推进从左向右移动。"},{"id":"wip","g":"team","word":"WIP 限制","text":"在制品：一列最多该放的卡片数，让团队先把事做完再开新的。","also":["WIP"]},{"id":"dod","g":"team","word":"完成的定义","text":"团队关于“完成”是什么意思的简短清单，比如已测试、已说明，然后才把卡片交给你。它的双胞胎“就绪的定义”，说的是卡片什么时候清楚到可以开工。","also":["Definition of Done","Definition of Ready","就绪的定义","DoD","DoR"]},{"id":"testpile","g":"team","word":"测试队列","text":"等你来试的已完成卡片，一张接一张。接受一张，或者附上说明退回去，下一张就出来了。","also":["test pile","test piles"]},{"id":"retro","g":"team","word":"回顾会","text":"回头看看团队是怎么工作的，商定一件可以做得更好的事。在 AI-gile 里，回顾会会提议改一改团队的工作方式，你说 Go 或者 还不行。","also":["回顾","retro","retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"同行评审","text":"多一双眼睛：另一个 AI 会在每张卡片的工作到达你之前检查一遍，这样漏掉的错误更少。","also":["代码评审","peer review","code review"]},{"id":"swarm","g":"team","word":"蜂群","text":"全员出动：每个团队放下手头的事，一起帮一个紧急项目，直到解决为止。其他项目这段时间先等着。","also":["集中攻关","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"让工作保持顺畅的人：发现卡住的卡片，催一催团队，并提醒你有什么在等着。在 AI-gile 里，由首席 Scrum Master 在所有项目里做这件事。","also":["首席 Scrum Master","Lead Scrum Master"]},{"id":"agent","g":"team","word":"智能体","text":"独立处理任务的 AI：读代码、做改动、运行检查，并汇报结果。","also":["agents","Agent","agent"]},{"id":"token","g":"team","word":"Token","text":"AI 用量的计量单位：大约相当于读写的几个字符。Token 越少，套餐剩得越多。","also":["tokens"]},{"id":"hook","g":"team","word":"钩子","text":"一条会在设定时刻自动运行的小命令，例如 AI 会话开始时，这样团队才能听到你的评论。","also":["hooks","Hook","hook"]}]}};
